import{_ as e,o as a,c as o,a2 as r}from"./chunks/framework.DgVVaeR-.js";const m=JSON.parse('{"title":"データベースと設定の保存","description":"","frontmatter":{"title":"データベースと設定の保存"},"headers":[],"relativePath":"dev/database-schema.md","filePath":"dev/database-schema.md","lastUpdated":1791023380000}'),d={name:"dev/database-schema.md"};function s(i,t,c,n,l,p){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="データベースと設定の保存" tabindex="-1">データベースと設定の保存 <a class="header-anchor" href="#データベースと設定の保存" aria-label="Permalink to &quot;データベースと設定の保存&quot;">​</a></h1><h2 id="メインのroom-db" tabindex="-1">メインのRoom DB <a class="header-anchor" href="#メインのroom-db" aria-label="Permalink to &quot;メインのRoom DB&quot;">​</a></h2><p><code>settings/db/IllustiaDatabase.java</code> は <code>illustia.db</code> を使用し、スキーマ版は <strong>7</strong> です。</p><table tabindex="0"><thead><tr><th>エンティティ</th><th>主な内容</th></tr></thead><tbody><tr><td><code>AccountEntity</code></td><td>userId、name、account、profileImageUrl、position。refreshTokenやisPremium列はない</td></tr><tr><td><code>SearchHistoryEntity</code></td><td>queryと表示順position</td></tr><tr><td><code>FavoriteTagEntity</code></td><td>tagと表示順position</td></tr><tr><td><code>ViewHistoryEntity</code></td><td>作品ID、タイトル、作者名、画像URL、ページ数、position、ブックマーク・年齢制限・タグ・AI区分など</td></tr><tr><td><code>SavedIllustEntity</code> / <code>SavedIllustPageEntity</code></td><td>保存作品の情報と各ページのファイル情報</td></tr></tbody></table><p><code>SavedIllustWithPages</code> は作品とページの関連を読み出すモデルです。これらのDB全体をSQLCipherなどで暗号化する指定はありません。</p><h2 id="pallasyncのroom-db" tabindex="-1">PallaSyncのRoom DB <a class="header-anchor" href="#pallasyncのroom-db" aria-label="Permalink to &quot;PallaSyncのRoom DB&quot;">​</a></h2><p><code>pallasync/data/PallaSyncDatabase.kt</code> は <code>pallasync_database</code> を使用し、スキーマ版は <strong>6</strong> です。outbox、チェーン状態、参加端末、受信inboxを別々のエンティティで保持します。DB更新時は各Databaseクラスのmigrationとfallback設定を確認してください。</p><h2 id="datastoreと秘密値" tabindex="-1">DataStoreと秘密値 <a class="header-anchor" href="#datastoreと秘密値" aria-label="Permalink to &quot;DataStoreと秘密値&quot;">​</a></h2><p><code>AppSettings</code> はアプリの設定モデルです。<code>SettingsStore</code> がPreferences DataStore、Room、EncryptedSharedPreferencesの値を集約します。すべてのプロパティがそのままDataStoreに保存されるわけではありません。</p><p>一般設定にはテーマ、画質、ダウンロード、ロック、PallaSync、テレメトリ等があります。作品・ユーザー・タグのミュート一覧と既読フィード作品は、別のPreferences DataStore（<code>illustia_collections</code>）に保存します。起動用の読み込みではこのファイルを開きません。既存の一覧は通常設定の初回読み込み時にコピーし、保存成功後に元ファイルから取り除きます。移行途中の失敗時は元データを優先して再試行します。認証トークンなどの秘密値は通常EncryptedSharedPreferencesで保護します。移行・暗号化ストアの初期化失敗時には、既存値を保持して再試行する処理があります。</p><p>フィールド追加時は <code>AppSettings</code> だけでなく、<code>settings/store/</code> の読み書き・移行、Roomへの投影、必要に応じて同期イベントの対象も確認してください。</p><p>実装: <a href="https://github.com/yunfie-twitter/Palleria/tree/main/app/src/main/java/com/yunfie/illustia/settings/db" target="_blank" rel="noreferrer">設定のDB</a>、<a href="https://github.com/yunfie-twitter/Palleria/tree/main/app/src/main/java/com/yunfie/illustia/settings/store" target="_blank" rel="noreferrer">保存処理</a>。</p>',12)])])}const b=e(d,[["render",s]]);export{m as __pageData,b as default};
